     1→// 🐀 Anti-Lie Solution 2: Hash-Chained Audit Log
     2→// Purpose: Create immutable proof of all state transitions
     3→// Philosophy: "The record is the proof"
     4→//
     5→// Every context switch:
     6→//   1. Hash the current state
     7→//   2. Chain it to previous hash
     8→//   3. Timestamp it
     9→//   4. This creates a tamper-proof audit trail
    10→//
    11→// To forge a record, attacker must:
    12→//   1. Change the state
    13→//   2. Recalculate the hash
    14→//   3. Recalculate ALL downstream hashes
    15→//   4. But that takes exponential time (detected)
    16→
    17→use std::collections::VecDeque;
    18→use std::fmt;
    19→use sha2::{Sha256, Digest};
    20→
    21→/// Individual audit entry
    22→#[derive(Debug, Clone)]
    23→pub struct AuditEntry {
    24→    pub sequence_number: u64,
    25→    pub timestamp: u128,
    26→    pub state_description: String,
    27→    pub stack_pointer: usize,
    28→    pub stack_drift: i64,
    29→    pub context_switch_count: u64,
    30→    pub current_hash: String,
    31→    pub previous_hash: String,
    32→}
    33→
    34→impl AuditEntry {
    35→    /// Compute SHA256 hash of this entry
    36→    pub fn compute_hash(&self) -> String {
    37→        let mut hasher = Sha256::new();
    38→
    39→        // Include all state to detect any modification
    40→        hasher.update(format!("{}", self.sequence_number).as_bytes());
    41→        hasher.update(format!("{}", self.timestamp).as_bytes());
    42→        hasher.update(self.state_description.as_bytes());
    43→        hasher.update(format!("{}", self.stack_pointer).as_bytes());
    44→        hasher.update(format!("{}", self.stack_drift).as_bytes());
    45→        hasher.update(format!("{}", self.context_switch_count).as_bytes());
    46→        hasher.update(self.previous_hash.as_bytes());
    47→
    48→        format!("{:x}", hasher.finalize())
    49→    }
    50→
    51→    /// Verify integrity - recompute hash and check match
    52→    pub fn verify(&self) -> bool {
    53→        let recomputed_hash = self.compute_hash();
    54→        recomputed_hash == self.current_hash
    55→    }
    56→}
    57→
    58→/// Hash-Chained Audit Log with tamper detection
    59→pub struct HashChainedAuditLog {
    60→    entries: VecDeque<AuditEntry>,
    61→    current_hash: String,
    62→    entry_count: u64,
    63→    pub total_hashes: u64,
    64→    pub verified_hashes: u64,
    65→    pub verification_failures: u64,
    66→    pub checkpoints: Vec<(u64, String)>,
    67→}
    68→
    69→impl HashChainedAuditLog {
    70→    pub fn new() -> Self {
    71→        // Genesis block
    72→        let genesis_hash = Self::compute_genesis_hash();
    73→
    74→        Self {
    75→            entries: VecDeque::new(),
    76→            current_hash: genesis_hash.clone(),
    77→            entry_count: 0,
    78→            total_hashes: 1,
    79→            verified_hashes: 1,
    80→            verification_failures: 0,
    81→            checkpoints: vec![(0, genesis_hash)],
    82→        }
    83→    }
    84→
    85→    /// Genesis block hash (no previous)
    86→    fn compute_genesis_hash() -> String {
    87→        let mut hasher = Sha256::new();
    88→        hasher.update(b"GENESIS_BLOCK");
    89→        format!("{:x}", hasher.finalize())
    90→    }
    91→
    92→    /// Record a context switch state transition
    93→    pub fn record_context_switch(
    94→        &mut self,
    95→        state_desc: &str,
    96→        stack_pointer: usize,
    97→        stack_drift: i64,
    98→        context_switch_count: u64,
    99→    ) {
   100→        let entry = AuditEntry {
   101→            sequence_number: self.entry_count,
   102→            timestamp: std::time::SystemTime::now()
   103→                .duration_since(std::time::UNIX_EPOCH)
   104→                .map(|d| d.as_micros())
   105→                .unwrap_or(0),
   106→            state_description: state_desc.to_string(),
   107→            stack_pointer,
   108→            stack_drift,
   109→            context_switch_count,
   110→            current_hash: String::new(), // Will be set below
   111→            previous_hash: self.current_hash.clone(),
   112→        };
   113→
   114→        // Compute hash with previous_hash included
   115→        let computed_hash = entry.compute_hash();
   116→
   117→        // Can't modify entry after this, so we need to construct properly
   118→        let mut final_entry = entry;
   119→        final_entry.current_hash = computed_hash.clone();
   120→
   121→        self.entries.push_back(final_entry);
   122→        self.current_hash = computed_hash;
   123→        self.entry_count += 1;
   124→        self.total_hashes += 1;
   125→
   126→        // Create checkpoint every 100,000 entries
   127→        if self.entry_count % 100_000 == 0 {
   128→            self.checkpoints.push((self.entry_count, self.current_hash.clone()));
   129→        }
   130→    }
   131→
   132→    /// Verify entire chain integrity
   133→    pub fn verify_chain_integrity(&mut self) -> bool {
   134→        println!("\n{}", "=".repeat(70));
   135→        println!("🔐 HASH CHAIN INTEGRITY VERIFICATION");
   136→        println!("{}", "=".repeat(70));
   137→
   138→        let mut verification_passed = true;
   139→        let mut consecutive_failures = 0;
   140→
   141→        // Verify each entry in chain
   142→        for (idx, entry) in self.entries.iter().enumerate() {
   143→            let recomputed_hash = entry.compute_hash();
   144→
   145→            if recomputed_hash != entry.current_hash {
   146→                println!(
   147→                    "❌ Hash mismatch at entry {}: computed={}, stored={}",
   148→                    idx,
   149→                    &recomputed_hash[..16],
   150→                    &entry.current_hash[..16]
   151→                );
   152→                verification_passed = false;
   153→                consecutive_failures += 1;
   154→                self.verification_failures += 1;
   155→            } else {
   156→                self.verified_hashes += 1;
   157→                consecutive_failures = 0;
   158→
   159→                if idx % 100_000 == 0 && idx > 0 {
   160→                    println!("  ✅ Entry {}: Hash verified (hash: {}...)", idx, &entry.current_hash[..16]);
   161→                }
   162→            }
   163→
   164→            // Detect tampering (consecutive failures indicate systematic attacks)
   165→            if consecutive_failures > 100 {
   166→                println!("🚨 TAMPERING DETECTED: {} consecutive hash failures!", consecutive_failures);
   167→                return false;
   168→            }
   169→        }
   170→
   171→        let total = self.entries.len();
   172→        let verified = self.verified_hashes as usize;
   173→
   174→        println!("\n{}", "=".repeat(70));
   175→        println!("✅ CHAIN VERIFICATION COMPLETE:");
   176→        println!("  Total Entries:        {}", total);
   177→        println!("  Verified Entries:     {} ({:.2}%)",
   178→            verified,
   179→            if total > 0 { (verified as f64 / total as f64) * 100.0 } else { 0.0 }
   180→        );
   181→        println!("  Failed Entries:       {}", self.verification_failures);
   182→        println!("  Checkpoints:          {}", self.checkpoints.len());
   183→        println!("  Chain Head Hash:      {}...", &self.current_hash[..16]);
   184→        println!("{}", "=".repeat(70));
   185→
   186→        verification_passed
   187→    }
   188→
   189→    /// Verify chain consistency from checkpoint
   190→    pub fn verify_from_checkpoint(&self, checkpoint_seq: u64) -> (bool, String) {
   191→        // Find checkpoint
   192→        let checkpoint = self.checkpoints.iter().find(|(seq, _)| *seq == checkpoint_seq);
   193→
   194→        if let Some((_, checkpoint_hash)) = checkpoint {
   195→            // Verify chain from this point forward
   196→            let mut current_hash = checkpoint_hash.clone();
   197→            let mut verified_count = 0;
   198→
   199→            for entry in self.entries.iter() {
   200→                if entry.sequence_number < checkpoint_seq {
   201→                    continue;
   202→                }
   203→
   204→                if entry.previous_hash != current_hash {
   205→                    return (false, format!(
   206→                        "Checkpoint {} integrity failed at entry {}",
   207→                        checkpoint_seq, entry.sequence_number
   208→                    ));
   209→                }
   210→
   211→                current_hash = entry.current_hash.clone();
   212→                verified_count += 1;
   213→            }
   214→
   215→            (true, format!("Verified {} entries from checkpoint {}", verified_count, checkpoint_seq))
   216→        } else {
   217→            (false, format!("Checkpoint {} not found", checkpoint_seq))
   218→        }
   219→    }
   220→
   221→    /// Get detailed chain report
   222→    pub fn get_chain_report(&self) -> String {
   223→        let mut report = format!(
   224→            "HASH-CHAINED AUDIT LOG REPORT\n\
   225→            {}\n\
   226→            Total Entries:           {}\n\
   227→            Total Hashes:            {}\n\
   228→            Verified Hashes:         {} ({:.2}%)\n\
   229→            Verification Failures:   {}\n\
   230→            Checkpoints Created:     {}\n\
   231→            Chain Head:              {}...\n\
   232→            Chain Integrity:         {}\n\
   233→            {}",
   234→            "=".repeat(60),
   235→            self.entry_count,
   236→            self.total_hashes,
   237→            self.verified_hashes,
   238→            if self.total_hashes > 0 {
   239→                (self.verified_hashes as f64 / self.total_hashes as f64) * 100.0
   240→            } else {
   241→                0.0
   242→            },
   243→            self.verification_failures,
   244→            self.checkpoints.len(),
   245→            &self.current_hash[..16],
   246→            if self.verification_failures == 0 { "✅ VALID" } else { "❌ COMPROMISED" },
   247→            "=".repeat(60)
   248→        );
   249→
   250→        if !self.checkpoints.is_empty() {
   251→            report.push_str("\n\nCHECKPOINTS:\n");
   252→            for (idx, (seq, hash)) in self.checkpoints.iter().enumerate() {
   253→                if idx % 10 == 0 || idx == self.checkpoints.len() - 1 {
   254→                    report.push_str(&format!("  Checkpoint {:2}: seq={:6}, hash={}...\n",
   255→                        idx, seq, &hash[..16]));
   256→                }
   257→            }
   258→        }
   259→
   260→        report
   261→    }
   262→
   263→    /// Get number of entries in chain
   264→    pub fn entry_count(&self) -> u64 {
   265→        self.entry_count
   266→    }
   267→
   268→    /// Get current chain hash
   269→    pub fn current_hash(&self) -> &str {
   270→        &self.current_hash
   271→    }
   272→}
   273→
   274→impl fmt::Display for HashChainedAuditLog {
   275→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
   276→        write!(
   277→            f,
   278→            "HashChainedAuditLog {{ entries: {}, current_hash: {}..., verified: {} }}",
   279→            self.entry_count,
   280→            &self.current_hash[..16.min(self.current_hash.len())],
   281→            self.verified_hashes
   282→        )
   283→    }
   284→}
