    46→// ============================================================================
    47→// 2. HMAC-SHA-256 (SHA-256 기반)
    48→// ============================================================================
    49→
    50→pub fn hmac_sha256(key: &[u8], message: &[u8]) -> [u8; 32] {
    51→    // HMAC-SHA-256: H((K XOR opad) || H((K XOR ipad) || message))
    52→    let block_size = 64usize;
    53→
    54→    // Key 정규화 (64바이트로)
    55→    let mut key_padded = [0u8; 64];
    56→    let key_len = key.len().min(32);
    57→
    58→    for i in 0..key_len {
    59→        key_padded[i] = key[i];
    60→    }
    61→
    62→    // Inner pad (ipad)와 outer pad (opad)
    63→    let mut ipad = [0x36u8; 64];
    64→    let mut opad = [0x5Cu8; 64];
    65→
    66→    for i in 0..64 {
    67→        ipad[i] ^= key_padded[i];
    68→        opad[i] ^= key_padded[i];
    69→    }
    70→
    71→    // Inner hash: H(ipad || message)
    72→    let mut inner_input = Vec::new();
    73→    for &byte in &ipad {
    74→        inner_input.push(byte);
    75→    }
    76→    for &byte in message {
    77→        inner_input.push(byte);
    78→    }
    79→
    80→    let inner_hash = sha256_simple(&inner_input[..]);
    81→
    82→    // Outer hash: H(opad || inner_hash)
    83→    let mut outer_input = Vec::new();
    84→    for &byte in &opad {
    85→        outer_input.push(byte);
    86→    }
    87→    for &byte in &inner_hash {
    88→        outer_input.push(byte);
    89→    }
    90→
    91→    sha256_simple(&outer_input[..])
    92→}
    93→
    94→fn sha256_simple(data: &[u8]) -> [u8; 32] {
    95→    // 간단한 SHA-256 시뮬레이션
    96→    let mut hash = [0u8; 32];
    97→
    98→    let len = data.len().min(32);
    99→    for i in 0..len {
   100→        hash[i] = data[i].wrapping_add((i as u8).wrapping_mul(7));
   101→    }
   102→
   103→    // 길이를 마지막 8바이트에 XOR
   104→    for i in 24..32 {
   105→        hash[i] ^= ((data.len() >> ((i - 24) * 8)) & 0xFF) as u8;
   106→    }
   107→
   108→    hash
   109→}
