   322→// 5. 검증 함수
   323→// ============================================================================
   324→
   325→pub fn validate_page_addr(addr: u64) -> bool {
   326→    let base = 0x80000000u64;
   327→    let top = base + (PAGE_COUNT as u64 * PAGE_SIZE as u64);
   328→    addr >= base && addr < top
   329→}
   330→
   331→pub fn validate_page_alignment(addr: u64) -> bool {
   332→    addr % PAGE_SIZE as u64 == 0
   333→}
   334→
   335→pub fn validate_allocation_count(count: u32) -> bool {
   336→    count > 0 && count <= PAGE_COUNT
   337→}
   338→
   339→pub fn validate_memory_size(size: u32) -> bool {
   340→    size > 0 && size <= MEMORY_POOL_SIZE
   341→}
   342→
   343→pub fn validate_pool_integrity(pool: &NanoPagePool) -> bool {
   344→    // 통계 검증
   345→    if pool.used_pages + pool.free_pages != pool.total_pages {
   346→        return false;
   347→    }
   348→
   349→    // 비트맵 검증 (0-1만 포함)
   350→    for i in 0..8 {
   351→        if pool.bitmap[i] > 0xFFFFFFFF {
   352→            return false;
   353→        }
   354→    }
   355→
   356→    true
   357→}
